/* Saveat — browser client. Authorization and inventory live in PostgreSQL. */
'use strict';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v)===0?'Gratis':new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(Number(v));
const when=v=>new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
let db=null,session=null,profile=null,current=null,myTab='listings',page=0,itemSequence=0,routeGeneration=0;
let searchCity=null,publishCity=null,pendingRequest=null,titleEdited=false,reservationFilter=null,mineGeneration=0,listingsSequence=0,notificationFingerprint=null;

const paymentLabels={cash:'Contanti',card:'Carta/POS',satispay:'Satispay'};
function paymentFields(prefix,selected=[]){return '<fieldset class="payment-options" id="'+prefix+'-payments"><legend>Metodi di pagamento accettati</legend>'+Object.entries(paymentLabels).map(([value,label])=>'<label class="container-check"><input type="checkbox" name="'+prefix+'-payment" value="'+value+'" '+(selected?.includes(value)?'checked':'')+'> '+label+'</label>').join('')+'<p class="small">Il pagamento avviene al punto di ritiro.</p></fieldset>';}
function selectedPayments(prefix){return [...document.querySelectorAll('input[name="'+prefix+'-payment"]:checked')].map(i=>i.value);}
function paymentSummary(methods,selling){if(!selling)return '';return '<p class="payment-summary"><b>Pagamenti accettati:</b> '+(methods?.length?methods.map(m=>esc(paymentLabels[m]||m)).join(', '):'Da concordare con chi vende')+' · al punto di ritiro.</p>';}
function descriptionBlock(text){return text?.trim()?'<div class="listing-description"><b>Descrizione</b><p>'+esc(text)+'</p></div>':'';}
function currentReservationInfo(item){const c=item.current_item;if(!c)return '';const changed=c.name!==item.name||c.unit!==item.unit;return (changed?'<p class="small"><b>Annuncio corretto:</b> '+esc(c.name)+' · '+esc(item.inventory_quantity??item.quantity)+' '+esc(c.unit)+'. La ricevuta iniziale e il totale restano conservati.</p>':'')+(c.label_date?'<p class="small">'+(c.date_type==='use_by'?'Da consumare entro':'Da consumarsi preferibilmente entro')+': '+esc(c.label_date)+'</p>':'')+(c.allergens?'<p class="small">Informazioni in etichetta: '+esc(c.allergens)+'</p>':'')+(c.container_provided!==item.container_provided?'<p class="small"><b>Indicazione aggiornata:</b> '+esc(containerMessage(c))+'</p>':'');}
function editUnitChoice(fs){const item=editListing.saveat_items.find(i=>i.id===fs.dataset.editItem),unit=fs.querySelector('[data-edit-field="unit"]').value,changed=unit!==item.unit,conversion=fs.querySelector('[data-edit-field="unit_conversion"]'),committed=Number(fs.dataset.committed),needs=changed&&committed>0;fs.querySelector('.unit-conversion').hidden=!needs;conversion.required=needs;const factor=needs?Number(conversion.value)||0:1,qty=fs.querySelector('[data-edit-field="quantity"]');qty.min=Math.max(['pezzi','confezioni'].includes(unit)?1:.001,committed*factor);qty.step=['pezzi','confezioni'].includes(unit)?'1':'.001';updateContainerChoice(fs,true);}

function syncListingTitle(){if(!titleEdited)$('title').value=$('item-fields').querySelector('[data-field="name"]')?.value.trim()||'';}
function refreshItemLabels(){[...$('item-fields').children].forEach((fs,index)=>{fs.querySelector('legend').textContent=index===0?'Cosa vuoi condividere?':'Alimento '+(index+1);fs.querySelector('.remove-item').hidden=$('item-fields').children.length===1;});syncListingTitle();}
const config=window.SAVEAT_CONFIG||{};
let notificationSequence=0;
async function refreshNotifications(){const seq=++notificationSequence,uid=session?.user.id;$('notifications-button').hidden=!uid;if(!uid){$('notification-alert').hidden=true;$('notifications-list').innerHTML='';notificationFingerprint=null;return;}
 const {data,error}=await db.from('saveat_notifications').select('id,title,message,created_at,read_at,reservation_id').eq('user_id',uid).order('created_at',{ascending:false}).limit(100);if(seq!==notificationSequence||session?.user.id!==uid)return;if(error){$('notifications-list').textContent='Impossibile aggiornare gli avvisi. Riprova.';return;}
 const fingerprint=uid+':'+data.map(n=>n.id+':'+(n.read_at||'')).join('|'),changed=notificationFingerprint!==null&&notificationFingerprint!==fingerprint;notificationFingerprint=fingerprint;$('notification-alert').hidden=true;const unread=data.filter(n=>!n.read_at);$('notifications-button').textContent='🔔 Avvisi'+(unread.length?' ('+unread.length+')':'');$('notifications-button').setAttribute('aria-label','Avvisi, '+unread.length+' non letti');if(unread.length){$('notification-alert').hidden=false;$('notification-alert').innerHTML='<b>Aggiornamenti sui tuoi ritiri.</b> Hai '+unread.length+' avvisi da leggere. <a href="#avvisi">Leggi gli avvisi prima del ritiro</a>';}
 $('notifications-list').innerHTML=data.map(n=>'<article class="card padded '+(!n.read_at?'notification-unread':'')+'"><span class="pill">'+(n.read_at?'Letto':'Nuovo avviso')+'</span><h2>'+esc(n.title)+'</h2><p>'+esc(n.message)+'</p><p class="small">'+esc(when(n.created_at))+'</p><a class="btn ghost" href="#miei" data-my-bookings>I miei ritiri</a>'+(!n.read_at?'<button class="ghost" data-read="'+n.id+'">Ho letto</button>':'')+'</article>').join('')||'<p class="empty">Nessun avviso.</p>';
 bindBookingLinks();if(changed&&location.hash==='#miei')await loadMine();
 document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>run(b,async()=>{await rpc('saveat_read_notification',{p_id:b.dataset.read});await refreshNotifications();}));}
function bindBookingLinks(){document.querySelectorAll('[data-my-bookings]').forEach(a=>a.onclick=e=>{e.preventDefault();reservationFilter=null;myTab='reservations';if(location.hash==='#miei')run(a,loadMine);else location.hash='miei';});}
$('notifications-button').onclick=()=>{location.hash='avvisi';};
setInterval(()=>{if(session&&document.visibilityState==='visible')refreshNotifications().catch(()=>{});},30000);
window.addEventListener('focus',()=>{if(session)run(null,async()=>{await refreshNotifications();if(location.hash==='#miei')await loadMine();});});
function notice(text,error=false){$('message').textContent=text;$('message').hidden=false;$('message').className=error?'error':'';}
function errorText(error){const t=error?.message||'Operazione non riuscita. Riprova.';if(/email not confirmed/i.test(t))return 'Email non ancora confermata. Apri il link nel messaggio più recente oppure richiedi una nuova conferma.';if(/email rate limit exceeded/i.test(t))return 'Limite temporaneo di invio email raggiunto. Attendi prima di richiedere un altro messaggio.';if(/invalid login credentials/i.test(t))return 'Email o password non corrette.';return /Failed to fetch|NetworkError|fetch failed/i.test(t)?'Connessione non disponibile. Controlla la rete e riprova.':t;}
async function run(button,work){if(button?.disabled)return;if(button)button.disabled=true;try{await work();}catch(e){notice(errorText(e),true);}finally{if(button)button.disabled=false;}}
async function rpc(name,args){const {data,error}=await db.rpc(name,args);if(error)throw error;return data;}
function rememberDestination(){const dest=location.hash;if(/^#(scheda\/[0-9a-f-]{36}|pubblica|miei)$/.test(dest))localStorage.setItem('saveat-return',dest);}
function continueAfterAuth(){localStorage.removeItem('saveat-return');location.hash='#home';}
function requireAccount(){if(!session){rememberDestination();location.hash='account';notice('Accedi oppure registrati per continuare. Dopo l’accesso arriverai alla Home.');return false;}if(!profile?.account_type){rememberDestination();location.hash='account';notice('Completa il profilo per continuare.');return false;}return true;}
async function refreshProfile(){const n=++profileRefreshSequence,uid=session?.user.id;profile=null;if(uid){const {data,error}=await db.from('saveat_profiles').select('*').eq('id',uid).single();if(n!==profileRefreshSequence||session?.user.id!==uid)return;if(error)throw error;profile=data;const meta=session.user.user_metadata||{};if(!profile.account_type&&meta.saveat_first&&meta.saveat_last&&['private','business'].includes(meta.saveat_type)){if(meta.saveat_city){await rpc('saveat_save_profile',{p_name:(meta.saveat_first+' '+meta.saveat_last).trim(),p_type:meta.saveat_type,p_business:meta.saveat_business||'',p_city:meta.saveat_city,p_radius:Number(meta.saveat_radius)||20,p_vat:meta.saveat_vat||'',p_address:meta.saveat_address||''});}else await rpc('saveat_set_profile',{p_name:(meta.saveat_first+' '+meta.saveat_last).trim(),p_type:meta.saveat_type,p_business:meta.saveat_business||''});const next=await db.from('saveat_profiles').select('*').eq('id',uid).single();if(n!==profileRefreshSequence||session?.user.id!==uid)return;if(next.error)throw next.error;profile=next.data;}}identityView();await applyProfileArea();}
function accountView(){const signed=!!session;$('account-heading').textContent=signed?'Il tuo profilo':'Accedi a Saveat';$('auth-form').hidden=signed;$('profile-form').hidden=!signed;
 if(signed){$('display-name').value=profile?.display_name||'';$('account-type').value=profile?.account_type||'private';$('account-type').disabled=!!profile?.account_type;$('business-name').value=profile?.business_name||'';businessView();profileLocationView();}}
function businessView(){const biz=$('account-type').value==='business';$('business-field').hidden=!biz;$('business-name').required=biz;$('vat-number').required=biz;$('business-address').required=biz;}

let visibleRoute=null,routeTrail=[],returningRoute=null;
function rememberRoute(next){
 const back=returningRoute&&returningRoute.hash===next?returningRoute:routeTrail.at(-1)?.hash===next?routeTrail.pop():null;returningRoute=null;
 if(visibleRoute&&visibleRoute.hash!==next&&!back)routeTrail.push({hash:visibleRoute.hash,scroll:window.scrollY});
 visibleRoute={hash:next};return back;
}
$('back-button').onclick=()=>{const previous=routeTrail.pop()||{hash:'#home',scroll:0};returningRoute=previous;location.hash=previous.hash;};
async function loadPersonalImpact(gen=routeGeneration){
 const target=$('personal-impact'),uid=session?.user.id;
 if(!uid){target.innerHTML='<p class="empty">Accedi per vedere il cibo che hai salvato.</p><a class="btn primary" href="#account">Accedi</a>';return;}
 target.textContent='Calcolo in corso…';
 try{const reservations=await rpc('saveat_my_reservations');if(gen!==routeGeneration||session?.user.id!==uid)return;
 const completed=[...new Map(reservations.filter(r=>r.status==='collected').map(r=>[r.id,r])).values()];
 const kg=completed.reduce((total,r)=>total+r.items.reduce((sum,i)=>sum+Number(i.quantity)*Number(i.saved_unit_kg??(i.unit==='kg'||i.unit==='litri'?1:.5)),0),0);
 target.innerHTML='<div class="card padded impact-card"><p>Cibo che hai contribuito a salvare</p><p class="impact-total">Circa '+new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(kg)+' kg</p><p>'+completed.length+(completed.length===1?' ritiro completato':' ritiri completati')+'</p></div>';
 }catch(e){if(gen===routeGeneration)target.textContent='Impatto temporaneamente non disponibile. Riapri questa pagina per riprovare.';}
}

async function route(){const gen=++routeGeneration;const [raw,id]=(location.hash.slice(1)||'home').split('/');let screen=['home','cerca','pubblica','scheda','miei','account','registrati','avvisi','modifica','setup','impatto'].includes(raw)?raw:'home';
 if(!db)screen='setup';else if(['pubblica','miei','modifica'].includes(screen)&&!requireAccount())return;
 const backState=rememberRoute('#'+screen+(id&&['scheda','modifica'].includes(screen)?'/'+id:''));$('back-button').hidden=screen==='home';
 document.querySelectorAll('.screen').forEach(s=>s.hidden=s.id!==screen);document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+screen)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});window.scrollTo(0,0);
 try{if(screen==='account')accountView();if(screen==='home')await Promise.all([loadListings('home-list',true,gen),loadImpact(gen)]);if(screen==='cerca'&&!backState){page=0;await loadListings('search-list',false,gen);}if(screen==='impatto')await loadPersonalImpact(gen);if(screen==='pubblica'&&!$('item-fields').children.length){addItem();preparePublication();}if(screen==='miei')await loadMine();if(screen==='avvisi')await refreshNotifications();if(screen==='scheda')await loadDetail(id);if(screen==='modifica')await loadEdit(id);if(backState&&gen===routeGeneration)window.scrollTo(0,backState.scroll);}catch(e){notice(errorText(e),true);}}
async function loadImpact(gen=routeGeneration){try{const impact=await rpc('saveat_impact');if(gen!==routeGeneration)return;const kg=Number(impact.saved_kg),pickups=Number(impact.completed_pickups);if(!Number.isFinite(kg)||!Number.isFinite(pickups))throw new Error('Totale non valido');$('impact-total').textContent='Circa '+new Intl.NumberFormat('it-IT',{maximumFractionDigits:2}).format(kg)+' kg';$('impact-pickups').textContent=pickups===1?'1 ritiro completato':new Intl.NumberFormat('it-IT').format(pickups)+' ritiri completati';}catch(error){if(gen===routeGeneration){$('impact-total').textContent='Totale temporaneamente non disponibile';$('impact-pickups').textContent='';}}}
function listingCard(l){const own=session?.user.id===l.owner_id;const photo=l.saveat_items?.find(i=>i.photo_path)?.photo_path;return `<article class="card">${photo?`<img class="photo" loading="lazy" src="${esc(db.storage.from('saveat-photos').getPublicUrl(photo).data.publicUrl)}" alt="Alimento disponibile">`:''}<div class="cardbody"><span class="pill">${own?'Pubblicato da te':l.account_type==='private'?'Privato':'Attività'}</span><h3>${esc(l.title)}</h3>${descriptionBlock(l.description)}${paymentSummary(l.payment_methods,(l.saveat_items||[]).some(i=>Number(i.price)>0))}<p class="meta">${esc(l.saveat_municipalities?.name)} (${esc(l.saveat_municipalities?.province)}) · ${esc(l.seller_name)}</p><p>Ritiro entro ${esc(when(l.pickup_end))}</p>${Number.isFinite(Number(l.distance_km))&&l.distance_km!=null?`<p class="small">Circa ${esc(Number(l.distance_km).toFixed(1))} km · centro del comune</p>`:''}<p>${(l.saveat_items||[]).filter(i=>Number(i.available)>0).map(i=>`${esc(i.name)} · ${esc(i.available)} ${esc(i.unit)} · ${money(i.price)}`).join('<br>')}</p><a class="btn primary" href="#scheda/${l.id}">${own?'Gestisci il tuo annuncio':'Vedi e prenota'}</a></div></article>`;}
async function loadListings(target,home,gen=routeGeneration){const seq=++listingsSequence,requestedPage=home?0:page,area=searchArea?{...searchArea}:null;$(target).innerHTML=requestedPage&&!home?$(target).innerHTML:'<p>Caricamento…</p>';
 if(!area){$(target).innerHTML='<p class="empty">Scegli il tuo comune o usa la posizione attuale per vedere gli alimenti vicini. <a href="#cerca">Imposta la zona</a></p>';$('load-more').hidden=true;return;}const size=home?4:20;const data=await rpc('saveat_search_nearby',{p_lat:area.lat,p_lon:area.lon,p_radius:area.radius,p_query:home?'':$('search').value.trim(),p_page:requestedPage,p_size:size});if(gen!==routeGeneration||seq!==listingsSequence)return;
 const visible=data.filter(l=>l.saveat_items.some(i=>Number(i.available)>0)),content=visible.map(listingCard).join('');
 if(requestedPage&&!home)$(target).insertAdjacentHTML('beforeend',content);else $(target).innerHTML=content||'<p class="empty">Nessun alimento disponibile in questa zona. Prova un raggio più ampio o un altro comune.</p>';
 if(!home)$('load-more').hidden=data.length<size;}
let editCity=null,editListing=null,editEnded=false,editLocked=false;
function ownListingActions(l){return '<div class="row owner-actions"><a class="btn primary" href="#modifica/'+l.id+'">Modifica annuncio</a><button type="button" class="ghost" data-close="'+l.id+'" '+(l.status==='closed'?'disabled title="Annuncio già annullato"':'')+'>Annulla annuncio</button><button type="button" class="ghost danger" data-delete="'+l.id+'">Elimina annuncio</button></div>';}
function bindDeleteActions(){document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Eliminare definitivamente questo annuncio anche dal tuo storico? Non potrai recuperarlo. Le prenotazioni ancora da ritirare saranno annullate con un avviso ai clienti; le loro ricevute resteranno disponibili.'))return;run(b,async()=>{await rpc('saveat_delete_listing',{p_id:b.dataset.delete});current=null;reservationFilter=null;myTab='listings';if(location.hash==='#miei')await loadMine();else location.hash='miei';await refreshNotifications();notice('Annuncio eliminato definitivamente dal tuo elenco e dallo storico.');});});}
function bindCloseActions(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{if(!confirm('Il cibo non è più disponibile? L’annuncio sarà annullato e chi deve ancora ritirare riceverà un avviso. Le consegne dei ritiri già segnalati resteranno da confermare.'))return;run(b,async()=>{await rpc('saveat_close_listing',{p_id:b.dataset.close});if(location.hash.startsWith('#scheda/'))await loadDetail(b.dataset.close);else await loadMine();await refreshNotifications();notice('Annuncio annullato. Avvisi registrati per chi doveva ancora ritirare.');});});}
const localDateTime=v=>{const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
async function loadEdit(id){if(!requireAccount())return;clearPhotoPreviews($('edit-items'));const gen=routeGeneration,uid=session.user.id;$('edit-form').hidden=true;editListing=null;editCity=null;
 const {data:l,error}=await db.from('saveat_listings').select('*,saveat_items(*),saveat_municipalities(name,province)').eq('id',id).single();if(gen!==routeGeneration||uid!==session?.user.id)return;if(error)throw error;if(l.owner_id!==uid)throw new Error('Puoi modificare solo i tuoi annunci.');
 const [p,all]=await Promise.all([db.from('saveat_pickup').select('*').eq('listing_id',id).single(),rpc('saveat_my_reservations')]);if(gen!==routeGeneration||uid!==session?.user.id)return;if(p.error)throw p.error;
 editListing=l;editEnded=l.status!=='active';const expired=new Date(l.pickup_end)<=new Date(),locked=all.some(r=>r.listing_id===id&&['reserved','confirmed'].includes(r.status));editLocked=locked;
 $('edit-title').value=l.title;$('edit-description').value=l.description;$('edit-start').value=localDateTime(l.pickup_start);$('edit-end').value=expired&&!locked&&!editEnded?'':localDateTime(l.pickup_end);if(expired&&!locked&&!editEnded)$('edit-start').value=localDateTime(new Date());$('edit-address').value=p.data.address;$('edit-contact').value=p.data.contact;$('edit-instructions').value=p.data.instructions;editCity={code:l.municipality_code,...l.saveat_municipalities};$('edit-city').value=editCity.name+' ('+editCity.province+')';
 for(const field of ['edit-city','edit-start','edit-end','edit-address','edit-contact','edit-instructions'])$(field).disabled=false;
 $('edit-note').textContent='Puoi correggere i dati senza ripubblicare. Chi ha una prenotazione attiva riceverà un avviso. Prezzi e ricevute già concordati restano conservati; la quantità totale deve coprire quanto già prenotato o consegnato.';
 $('edit-payment-fields').innerHTML=paymentFields('edit',l.payment_methods);
 $('edit-items').innerHTML=l.saveat_items.map(i=>{const reserved=all.some(r=>r.items.some(ri=>ri.item_id===i.id)),stop=false,committed=all.filter(r=>r.listing_id===id&&['reserved','confirmed','collected'].includes(r.status)).reduce((sum,r)=>sum+r.items.filter(ri=>ri.item_id===i.id).reduce((n,ri)=>n+Number(ri.inventory_quantity??ri.quantity),0),0);return '<fieldset class="item-field" data-edit-item="'+i.id+'" data-committed="'+committed+'"><legend>'+esc(i.name)+'</legend><label>Nome alimento<input data-edit-field="name" required minlength="2" maxlength="120" value="'+esc(i.name)+'" '+(stop?'disabled':'')+'></label><label>Quantità totale<input type="number" data-edit-field="quantity" required min="'+Math.max(['pezzi','confezioni'].includes(i.unit)?1:.001,committed)+'" max="9999999" step="'+(['kg','litri'].includes(i.unit)?'.001':'1')+'" value="'+i.quantity+'" '+''+'></label><p class="small">'+esc(committed)+' unità già prenotate o ritirate.</p><label>Unità<select data-edit-field="unit" '+(stop?'disabled':'')+'>'+['confezioni','pezzi','kg','litri'].map(u=>'<option '+(u===i.unit?'selected':'')+'>'+u+'</option>').join('')+'</select></label>'+containerFields(i.container_provided===true,true,false)+'<div class="unit-conversion" hidden><label>Una unità precedente corrisponde a quante nuove unità?<input data-edit-field="unit_conversion" type="number" min="0.000001" max="1000000" step="any"></label><p class="small">Indica la conversione solo se cambi unità con quantità già prenotate o consegnate, poi correggi la quantità totale.</p></div><label>Tipo di data in etichetta<select data-edit-field="date_type"><option value="none" '+(i.date_type==='none'?'selected':'')+'>Nessuna data</option><option value="use_by" '+(i.date_type==='use_by'?'selected':'')+'>Da consumare entro</option><option value="best_before" '+(i.date_type==='best_before'?'selected':'')+'>Da consumarsi preferibilmente entro</option></select></label><label>Data sulla confezione<input data-edit-field="label_date" type="date" value="'+esc(i.label_date||'')+'"></label><label>Informazioni in etichetta / allergeni<textarea data-edit-field="allergens" maxlength="500">'+esc(i.allergens)+'</textarea></label><p class="small">La scelta vale per le nuove prenotazioni; quelle già effettuate mantengono l’indicazione iniziale.</p><label>Per le quantità rimaste<select data-edit-field="offer" '+''+'><option value="donate" '+(Number(i.price)===0?'selected':'')+'>Dona</option><option value="sell" '+(Number(i.price)>0?'selected':'')+'>Vendi</option></select></label><label class="edit-price" '+(Number(i.price)===0?'hidden':'')+'>Prezzo per unità (€)<input type="number" data-edit-field="price" min="0.01" max="99999999" step=".01" value="'+i.price+'" '+''+'></label><p class="small">'+esc(Number(i.quantity)-committed)+' '+esc(i.unit)+' rimaste. Il nuovo prezzo vale solo per le nuove prenotazioni.</p>'+photoControls(i.photo_path)+'<label>Peso per unità in grammi (facoltativo)<input type="number" data-edit-field="weight" min="1" max="1000000" step="1" value="'+(i.unit_weight_kg?Number(i.unit_weight_kg)*1000:'')+'" '+''+'></label><p class="small">Il peso aggiornato vale per i prossimi ritiri. Se manca: 500 g per pezzo/confezione, circa 1 kg per litro. Per kg usiamo la quantità.</p></fieldset>';}).join('');document.querySelectorAll('[data-edit-item]').forEach(fieldset=>{const offer=fieldset.querySelector('[data-edit-field="offer"]'),price=fieldset.querySelector('[data-edit-field="price"]');const update=()=>{const selling=offer.value==='sell';fieldset.querySelector('.edit-price').hidden=!selling;price.required=selling;$('edit-payment-fields').hidden=![...document.querySelectorAll('[data-edit-field="offer"]')].some(el=>el.value==='sell');};offer.onchange=update;update();updateContainerChoice(fieldset,true);fieldset.querySelector('[data-edit-field="unit"]').onchange=()=>editUnitChoice(fieldset);fieldset.querySelector('[data-edit-field="unit_conversion"]').oninput=()=>editUnitChoice(fieldset);editUnitChoice(fieldset);const dateType=fieldset.querySelector('[data-edit-field="date_type"]'),date=fieldset.querySelector('[data-edit-field="label_date"]');dateType.onchange=()=>{date.required=dateType.value!=='none';};dateType.onchange();bindPhotoControls(fieldset);});$('edit-back').href='#scheda/'+id;$('edit-form').hidden=false;}
$('edit-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{if(!requireAccount()||!editListing||editListing.owner_id!==session.user.id)throw new Error('Riapri il tuo annuncio.');if(!editCity)throw new Error('Seleziona il comune dai suggerimenti.');const id=editListing.id;if([...document.querySelectorAll('[data-edit-field="offer"]')].some(i=>i.value==='sell')&&!selectedPayments('edit').length)throw new Error('Seleziona almeno un metodo di pagamento.');const items=await Promise.all([...document.querySelectorAll('[data-edit-item]')].map(async fs=>{const get=k=>fs.querySelector('[data-edit-field="'+k+'"]').value;return {id:fs.dataset.editItem,name:get('name'),quantity:Number(get('quantity')),unit:get('unit'),price:get('offer')==='donate'?0:Number(get('price')),date_type:get('date_type'),label_date:get('label_date')||null,allergens:get('allergens'),unit_conversion:get('unit_conversion')?Number(get('unit_conversion')):null,unit_weight_kg:get('weight')?Number(get('weight'))/1000:null,container_provided:get('unit')==='confezioni'||fs.querySelector('[data-edit-field="container"]').checked,...(fs.photoRemoved?{photo_path:null}:fs.photoFile?{photo_path:await uploadPhoto(fs)}:{})};}));if([...document.querySelectorAll('[data-edit-item]')].some(fs=>fs.photoPending))throw new Error('Attendi che la foto sia pronta.');await rpc('saveat_update_listing',{p_id:id,p_listing:{title:$('edit-title').value,description:$('edit-description').value,municipality_code:editCity.code,pickup_start:new Date($('edit-start').value).toISOString(),pickup_end:new Date($('edit-end').value).toISOString(),address:$('edit-address').value,contact:$('edit-contact').value,instructions:$('edit-instructions').value,payment_methods:selectedPayments('edit')},p_items:items});clearPhotoPreviews($('edit-items'));editListing=null;location.hash='scheda/'+id;notice('Modifiche salvate. Chi ha prenotato riceve un avviso; il prezzo già concordato resta conservato.');});};


let ownerBookingsSequence=0;
function ownerBookingCard(r){return '<article class="owner-booking"><p><b>'+esc(r.customer_name||'Utente Saveat')+'</b> <span class="pill">'+esc(r.customer_collected_at&&['reserved','confirmed'].includes(r.status)?'Consegna da confermare':(r.status==='collected'?'Consegnato':statusNames[r.status]||r.status))+'</span></p><ul>'+r.items.map(i=>'<li>'+esc(i.name)+' · <b>'+esc(i.quantity)+' '+esc(i.unit)+'</b>'+currentReservationInfo(i)+'</li>').join('')+'</ul><p class="small">Codice: '+esc(r.id.slice(0,8))+'</p></article>';}
function ownerBookingsView(l,all,uid){
 const bookings=all.filter(r=>r.listing_id===l.id&&r.owner_id===uid),active=bookings.filter(r=>['reserved','confirmed'].includes(r.status)),collected=bookings.filter(r=>r.status==='collected');
 const totals=l.saveat_items.map(i=>{const sum=rows=>rows.reduce((n,r)=>n+r.items.filter(ri=>ri.item_id===i.id).reduce((s,ri)=>s+Number(ri.inventory_quantity??ri.quantity),0),0);return '<li><b>'+esc(i.name)+'</b><br>'+esc(sum(active))+' '+esc(i.unit)+' prenotati da consegnare · '+esc(i.available)+' disponibili'+(sum(collected)>0?' · '+esc(sum(collected))+' consegnati':'')+'</li>';}).join('');
 return '<ul class="owner-stock">'+totals+'</ul>'+(active.length?'<h3>Chi ritira e cosa ('+active.length+')</h3>'+active.map(ownerBookingCard).join(''):'<p class="small">Nessuna prenotazione da consegnare per questo annuncio.</p>')+summaryGroup('Consegne completate',collected,ownerBookingCard,true)+summaryGroup('Prenotazioni annullate o scadute',bookings.filter(r=>['cancelled','expired'].includes(r.status)),ownerBookingCard,true)+(bookings.length?'<a class="btn primary" href="#miei" id="manage-owner-bookings">Gestisci queste consegne</a>':'');
}
async function loadOwnerBookings(l,gen=routeGeneration){
 const uid=session?.user.id,target=$('owner-bookings'),seq=++ownerBookingsSequence;
 if(!target||!uid||l.owner_id!==uid)return;
 const fresh=()=>seq===ownerBookingsSequence&&gen===routeGeneration&&uid===session?.user.id&&current?.id===l.id&&$('owner-bookings')===target;
 target.textContent='Caricamento prenotazioni…';
 try{const all=await rpc('saveat_my_reservations');if(!fresh())return;target.innerHTML=ownerBookingsView(l,all,uid);
 const manage=$('manage-owner-bookings');if(manage)manage.onclick=e=>{e.preventDefault();reservationFilter=l.id;myTab='received';location.hash='miei';};
 }catch(e){if(fresh())target.innerHTML='<p class="error">Impossibile caricare le prenotazioni. Premi Aggiorna per riprovare.</p>';}
}

async function loadDetail(id){const detailRequest=routeGeneration,detailAccount=session?.user.id;$('detail').innerHTML='<p>Caricamento…</p>';pendingRequest=null;
 const {data:l,error}=await db.from('saveat_listings').select('*,saveat_items(*),saveat_municipalities(name,province)').eq('id',id).single();if(detailRequest!==routeGeneration||detailAccount!==session?.user.id)return;if(error){if(error.code==='PGRST116'){$('detail').innerHTML='<h1>Annuncio non disponibile</h1><p>Questo annuncio è stato eliminato o non è più visibile.</p><a class="btn primary" href="#cerca">Cerca altri alimenti</a>';return;}throw error;}current=l;
 const owner=session?.user.id===l.owner_id,availableItems=l.saveat_items.filter(i=>Number(i.available)>0),active=l.status==='active'&&new Date(l.pickup_end)>new Date()&&availableItems.length>0;
 $('detail').innerHTML=`<h1>${esc(l.title)}</h1>${descriptionBlock(l.description)}${paymentSummary(l.payment_methods,l.saveat_items.some(i=>Number(i.price)>0))}<p>${esc(l.saveat_municipalities.name)} (${esc(l.saveat_municipalities.province)}) · ${esc(l.seller_name)}</p><p>Ritiro: ${esc(when(l.pickup_start))} – ${esc(when(l.pickup_end))}</p>${owner?'<section class="card padded owner-bookings-panel" aria-labelledby="owner-bookings-heading"><div class="row"><h2 id="owner-bookings-heading">Prenotazioni ricevute</h2><button type="button" id="refresh-owner-bookings" class="ghost">Aggiorna</button></div><div id="owner-bookings" aria-live="polite"></div></section>':''}<p class="ethic"><b>Porta sempre una borsa per il ritiro.</b></p><form id="reserve-form">${l.saveat_items.map(i=>`<div class="product">${i.photo_path?`<img class="photo" src="${esc(db.storage.from('saveat-photos').getPublicUrl(i.photo_path).data.publicUrl)}" alt="${esc(i.name)}">`:''}<h2>${esc(i.name)}</h2><p>${esc(i.available)} ${esc(i.unit)} disponibili · ${money(i.price)} / ${esc(i.unit)}</p><p class="pickup-container">${esc(containerMessage(i))}</p>${i.label_date?`<p>${i.date_type==='use_by'?'Da consumare entro':'Da consumarsi preferibilmente entro'}: ${esc(i.label_date)}</p>`:''}${i.allergens?`<p class="small">Informazioni in etichetta: ${esc(i.allergens)}</p>`:''}${active&&!owner?`<label for="qty-${i.id}">Quantità da prenotare (${esc(i.unit)})</label><input class="qty" id="qty-${i.id}" data-item="${i.id}" type="number" min="0" max="${i.available}" step="${['kg','litri'].includes(i.unit)?'.001':'1'}" value="${availableItems.length===1?Math.min(1,Number(i.available)):0}" ${Number(i.available)<=0?'disabled':''}>`:''}</div>`).join('')}${active&&!owner?'<div class="ethic">Prenota solo ciò che consumerai. Dopo la prenotazione vedrai i dettagli per il ritiro.</div><p id="reservation-total" class="ethic" aria-live="polite"></p><button class="primary full">Conferma prenotazione</button>':`<p class="ethic">${owner?'Questo è il tuo annuncio. Usa i comandi qui sotto.':l.status==='active'&&new Date(l.pickup_end)>new Date()?'Tutti gli alimenti sono già prenotati.':'Annuncio non più disponibile.'}</p>`}</form>${owner?ownListingActions(l):''}`;
 if(owner){$('refresh-owner-bookings').onclick=()=>run($('refresh-owner-bookings'),()=>loadDetail(l.id));await loadOwnerBookings(l,detailRequest);if(detailRequest!==routeGeneration||detailAccount!==session?.user.id)return;}
 bindCloseActions();bindDeleteActions();if(active&&!owner){$('reserve-form').addEventListener('input',()=>updateReservationTotal(l));updateReservationTotal(l);}
 $('reserve-form').addEventListener('submit',e=>{e.preventDefault();run(e.submitter,async()=>{if(!requireAccount())return;const items=[...document.querySelectorAll('[data-item]')].map(i=>({item_id:i.dataset.item,quantity:Number(i.value)})).filter(i=>i.quantity>0);if(!items.length)throw new Error('Scegli almeno un alimento.');const signature=JSON.stringify(items);if(!pendingRequest||pendingRequest.signature!==signature)pendingRequest={signature,id:crypto.randomUUID()};await rpc('saveat_reserve',{p_listing_id:l.id,p_items:items,p_request_id:pendingRequest.id});pendingRequest=null;reservationFilter=null;myTab='reservations';location.hash='miei';notice('Prenotazione confermata automaticamente. Trovi i dettagli in I miei Save → I miei ritiri.');});});}
function updateReservationTotal(l){let total=0,count=0;document.querySelectorAll('[data-item]').forEach(input=>{const item=l.saveat_items.find(i=>i.id===input.dataset.item),quantity=Number(input.value);if(item&&Number.isFinite(quantity)&&quantity>0){count++;total+=quantity*Number(item.price);}});$('reservation-total').textContent=count?(total>0?'Totale da pagare al ritiro: '+money(total):'Donazione gratuita · nessun pagamento'):'Scegli gli alimenti e le quantità da prenotare.';}
