function adjustItemQuantity(fs){const input=fs.querySelector('[data-field="quantity"]'),unit=fs.querySelector('[data-field="unit"]').value,whole=['pezzi','confezioni'].includes(unit);input.step=whole?'1':'.001';input.min=whole?'1':'.001';}

function photoControls(path=null){return '<div class="photo-picker"><div class="row"><button type="button" class="ghost photo-gallery">Aggiungi foto</button><button type="button" class="ghost photo-camera">Scatta foto</button><button type="button" class="ghost photo-remove">Rimuovi foto</button></div><input class="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" hidden><input class="photo-capture" type="file" accept="image/*" capture="environment" hidden><img class="photo photo-preview" alt="Anteprima foto completa" '+(path?'src="'+esc(db.storage.from('saveat-photos').getPublicUrl(path).data.publicUrl)+'"':'hidden')+'><p class="small photo-status" aria-live="polite">La foto viene adattata senza tagli. Scatta foto usa la fotocamera sui cellulari compatibili.</p></div>';}
async function preparePhoto(file){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Usa una foto JPG, PNG o WebP. Se il telefono salva in HEIC, scegli il formato JPG.');
 if(file.size>26214400)throw new Error('Foto troppo grande: scegli un file entro 25 MB.');
 let picture,url;try{
 if(typeof createImageBitmap==='function')picture=await createImageBitmap(file,{imageOrientation:'from-image'});else{url=URL.createObjectURL(file);picture=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Non riesco a leggere questa foto. Scegline un’altra.'));img.src=url;});}
 const width=picture.width||picture.naturalWidth,height=picture.height||picture.naturalHeight,scale=Math.min(1,1800/Math.max(width,height));
 if(scale===1&&file.size<=5242880)return file;
 const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(width*scale));canvas.height=Math.max(1,Math.round(height*scale));canvas.getContext('2d').drawImage(picture,0,0,canvas.width,canvas.height);
 let blob=await new Promise(resolve=>canvas.toBlob(resolve,file.type==='image/png'?'image/png':'image/jpeg',.85));
 if(blob&&blob.size>5242880)blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.8));
 if(!blob||blob.size>5242880)throw new Error('Non riesco a ridurre questa foto entro 5 MB. Scegli una foto più piccola.');return blob;
 }finally{picture?.close?.();if(url)URL.revokeObjectURL(url);}
}
function bindPhotoControls(fieldset){const picker=fieldset.querySelector('.photo-picker'),gallery=picker.querySelector('.photo-upload'),camera=picker.querySelector('.photo-capture'),preview=picker.querySelector('.photo-preview'),status=picker.querySelector('.photo-status');picker.querySelector('.photo-gallery').onclick=()=>gallery.click();picker.querySelector('.photo-camera').onclick=()=>camera.click();let sequence=0;picker.querySelector('.photo-remove').onclick=()=>{sequence++;fieldset.photoPending=false;fieldset.photoFile=null;fieldset.photoRemoved=true;if(fieldset.photoPreviewUrl)URL.revokeObjectURL(fieldset.photoPreviewUrl);fieldset.photoPreviewUrl=null;preview.removeAttribute('src');preview.hidden=true;status.textContent='Foto rimossa. Salva le modifiche per confermare.';};
 const choose=async input=>{const file=input.files[0];if(!file)return;const seq=++sequence;fieldset.photoPending=true;status.textContent='Adatto la foto…';try{const prepared=await preparePhoto(file);if(seq!==sequence)return;fieldset.photoFile=prepared;fieldset.photoRemoved=false;if(fieldset.photoPreviewUrl)URL.revokeObjectURL(fieldset.photoPreviewUrl);fieldset.photoPreviewUrl=URL.createObjectURL(prepared);preview.src=fieldset.photoPreviewUrl;preview.hidden=false;status.textContent='Foto pronta: viene mostrata intera.';}catch(error){if(seq===sequence){status.textContent=error.message;notice(error.message,true);}}finally{if(seq===sequence)fieldset.photoPending=false;input.value='';}};
 gallery.onchange=()=>choose(gallery);camera.onchange=()=>choose(camera);
}
function clearPhotoPreviews(container){(container.querySelectorAll?.('.item-field')||[]).forEach(fieldset=>{if(fieldset.photoPreviewUrl)URL.revokeObjectURL(fieldset.photoPreviewUrl);});}
async function uploadPhoto(fieldset){if(fieldset.photoPending)throw new Error('Attendi che la foto sia pronta.');const file=fieldset.photoFile;if(!file)return null;const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type];if(!ext||file.size>5242880)throw new Error('Foto non valida.');const path=session.user.id+'/'+crypto.randomUUID()+'.'+ext;const {error}=await db.storage.from('saveat-photos').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;return path;}

function containerFields(provided=false,edit=false,disabled=false){return '<div class="container-choice"><label class="container-check"><input type="checkbox" '+(edit?'data-edit-field':'data-field')+'="container" '+(provided?'checked':'')+' '+(disabled?'disabled':'')+'> <span>Fornisco io il contenitore</span></label><p class="small">Se non selezioni questa casella, chi prenota sarà avvisato di portare il proprio contenitore.</p></div><p class="small packaged-note" hidden>Prodotto in confezione: per il ritiro basta una borsa.</p>';}
function updateContainerChoice(fieldset,edit=false){const prefix=edit?'data-edit-field':'data-field',packaged=fieldset.querySelector('['+prefix+'="unit"]').value==='confezioni',input=fieldset.querySelector('['+prefix+'="container"]');fieldset.querySelector('.container-choice').hidden=packaged;fieldset.querySelector('.packaged-note').hidden=!packaged;input.disabled=packaged;}
