function addItem(){if($('item-fields').children.length>=20){notice('Massimo 20 alimenti per annuncio.',true);return;}const n=++itemSequence;const fs=document.createElement('fieldset');fs.className='item-field';fs.dataset.sequence=n;const field=(name,label,type='text',extra='')=>`<label for="item-${n}-${name}">${label}</label><input id="item-${n}-${name}" data-field="${name}" type="${type}" ${extra}>`;
 fs.innerHTML=`<legend>Alimento ${n}</legend>${field('name','Nome dell’alimento','text','required minlength="2" maxlength="120"')}<div class="two"><div>${field('quantity','Quantità disponibile','number','required min="0.001" max="9999999" step="0.001"')}</div><div><label for="item-${n}-unit">Unità</label><select id="item-${n}-unit" data-field="unit"><option>confezioni</option><option>pezzi</option><option>kg</option><option>litri</option></select></div></div>${containerFields()}<div class="item-price" hidden>${field('price','Prezzo per unità (€)','number','min="0.01" max="99999999" step="0.01" placeholder="Es. 2,50"')}</div><details class="item-extras"><summary>Foto e data sulla confezione (facoltative)</summary><label for="item-${n}-date-type">Tipo di data in etichetta</label><select id="item-${n}-date-type" data-field="date_type"><option value="none">Nessuna data</option><option value="use_by">Da consumare entro (scadenza)</option><option value="best_before">Da consumarsi preferibilmente entro</option></select>${field('label_date','Data sulla confezione','date')}${field('allergens','Informazioni in etichetta / allergeni','text','maxlength="500"')}${photoControls()}${field('weight','Peso per unità in grammi (facoltativo)','number','min="1" max="1000000" step="1" placeholder="Es. 500"')}<p class="small">Se manca, stimiamo 500 g per pezzo/confezione; 1 litro ≈ 1 kg. Per alimenti in kg usiamo la quantità indicata.</p><p class="small">Non includere indirizzi, contatti o persone nelle foto pubbliche.</p></details><button type="button" class="ghost remove-item">Rimuovi alimento</button>`;
 fs.querySelector('.remove-item').onclick=()=>{if($('item-fields').children.length>1){if(fs.photoPreviewUrl)URL.revokeObjectURL(fs.photoPreviewUrl);fs.remove();refreshItemLabels();}};fs.querySelector('[data-field="name"]').oninput=syncListingTitle;fs.querySelector('[data-field="unit"]').onchange=()=>{adjustItemQuantity(fs);updateContainerChoice(fs);};adjustItemQuantity(fs);updateContainerChoice(fs);fs.querySelector('[data-field="date_type"]').onchange=e=>{const date=fs.querySelector('[data-field="label_date"]');date.required=e.target.value!=='none';if(date.required)fs.querySelector('details').open=true;};bindPhotoControls(fs);$('item-fields').append(fs);refreshItemLabels();updateOfferMode();}
function updateOfferMode(){if(!$('publish-payment-fields').innerHTML)$('publish-payment-fields').innerHTML=paymentFields('publish',['cash']);$('publish-payment-fields').hidden=$('offer-mode').value!=='sell';const selling=$('offer-mode').value==='sell';document.querySelectorAll('#item-fields .item-field').forEach(fs=>{const input=fs.querySelector('[data-field="price"]');fs.querySelector('.item-price').hidden=!selling;input.required=selling;input.disabled=!selling;});}
async function publish(){if(!requireAccount())return;if($('offer-mode').value==='sell'&&!selectedPayments('publish').length)throw new Error('Seleziona almeno un metodo di pagamento.');if(!publishCity)throw new Error('Seleziona un comune dai suggerimenti.');const start=new Date($('pickup-start').value),end=new Date($('pickup-end').value);if(end<=new Date()||end<=start)throw new Error('Controlla la fascia di ritiro.');
 const items=[];for(const fs of $('item-fields').children){const get=f=>fs.querySelector(`[data-field="${f}"]`);const item={name:get('name').value,quantity:Number(get('quantity').value),unit:get('unit').value,price:$('offer-mode').value==='sell'?Number(get('price').value):0,date_type:get('date_type').value,label_date:get('label_date').value||null,allergens:get('allergens').value,photo_path:null,unit_weight_kg:get('weight').value?Number(get('weight').value)/1000:null,container_provided:get('unit').value==='confezioni'||get('container').checked};
  if($('offer-mode').value==='sell'&&(!Number.isFinite(item.price)||item.price<0.01))throw new Error('Inserisci il prezzo per unità per ogni alimento.');
  if(['pezzi','confezioni'].includes(item.unit)&&!Number.isInteger(item.quantity))throw new Error('Pezzi e confezioni richiedono quantità intere.');
  item.photo_path=await uploadPhoto(fs);items.push(item);}
 await rpc('saveat_create_listing',{p_listing:{title:$('title').value,description:$('description').value,municipality_code:publishCity.code,pickup_start:start.toISOString(),pickup_end:end.toISOString(),address:$('address').value,contact:$('contact').value,instructions:$('instructions').value,payment_methods:$('offer-mode').value==='sell'?selectedPayments('publish'):[]},p_items:items});$('publish-form').reset();$('publish-payment-fields').innerHTML='';clearPhotoPreviews($('item-fields'));$('item-fields').replaceChildren();publishCity=null;location.hash='miei';myTab='listings';notice('Annuncio pubblicato.');}
const statusNames={reserved:'Prenotato',confirmed:'Confermato',collected:'Ritirato',cancelled:'Annullato',expired:'Scaduto'};
function reservationSummaryCard(r){const owner=r.owner_id===session.user.id,active=['reserved','confirmed'].includes(r.status);return `<article class="card padded ${owner?'summary-received':'summary-booked'}"><span class="pill">${active?(owner?'Da consegnare':'Da ritirare'):(r.status==='collected'?(owner?'Consegna completata':'Ritiro completato'):r.status==='expired'?(owner?'Prenotazione scaduta':'Ritiro scaduto'):'Prenotazione annullata')}</span>${active?`<p class="small">${r.customer_collected_at?(owner?"Ritiro segnalato · consegna da confermare":"Ritiro segnalato · in attesa di conferma"):esc(statusNames[r.status])}</p>`:""}<h2>${esc(r.title)}</h2>${descriptionBlock(r.description)}${owner?`<p><b>Prenotato da:</b> ${esc(r.customer_name||'Utente Saveat')}</p>`:''}<p class="small">Codice: ${esc(r.id.slice(0,8))}</p><p>${r.items.map(i=>`${esc(i.name)} · ${esc(i.quantity)} ${esc(i.unit)} · ${money(Number(i.price)*Number(i.quantity))}<br><span class="small">${esc(containerMessage(i))}</span>${currentReservationInfo(i)}`).join('<br>')}</p><p>Totale: ${money(r.items.reduce((s,i)=>s+Number(i.quantity)*Number(i.price),0))}</p>${paymentSummary(r.payment_methods,r.items.some(i=>Number(i.price)>0))}${r.status==="cancelled"&&r.cancellation_reason==="owner_unavailable"?`<p class="unavailable-alert" role="status"><b>Cibo non disponibile.</b> Chi pubblica ha annullato il ritiro. Non recarti al punto di incontro.</p>`:""}<p>${active?(owner?"Consegna al punto di ritiro":"Ritiro"):"Fascia prevista"}: ${esc(when(r.pickup_start))} – ${esc(when(r.pickup_end))}</p>${active?'<p class="ethic"><b>Porta sempre una borsa per il ritiro.</b></p>':''}${r.pickup?`<div class="ethic"><b>Punto di ritiro</b><p>${esc(r.pickup.address)}</p><p>Contatto: ${esc(r.pickup.contact)}</p><p>${esc(r.pickup.instructions)}</p></div>`:''}<div class="row">${active&&owner&&new Date(r.pickup_start)<=new Date()?`<button class="primary" data-transition="collected" data-id="${r.id}">Conferma consegna</button>`:''}${active&&!owner&&!r.customer_collected_at&&new Date(r.pickup_start)<=new Date()?`<button class="primary" data-report="${r.id}">Ho ritirato</button>`:''}${active&&r.customer_collected_at?`<p class="small">${owner?'Chi ha prenotato ha segnalato il ritiro. Conferma la consegna per completarla.':'Hai segnalato il ritiro. In attesa della conferma di chi pubblica.'}</p>`:''}${active&&!r.customer_collected_at?`<button class="ghost" data-transition="cancelled" data-id="${r.id}">Annulla prenotazione</button>`:''}</div>${r.listing_id?`<a class="btn ghost" href="#scheda/${r.listing_id}">Vedi annuncio</a>`:''}${owner&&r.listing_id?ownListingActions({id:r.listing_id,status:r.listing_status||'active'}):''}</article>`;}
function summaryGroup(title,rows,render,history=false){if(!rows.length)return '';const content=rows.map(render).join('');return history?'<details class="summary-history"><summary>'+esc(title)+' ('+rows.length+')</summary>'+content+'</details>':'<section class="summary-group"><h3>'+esc(title)+' <span class="count">'+rows.length+'</span></h3>'+content+'</section>';}
async function loadMine(){if(!requireAccount())return;const mineRequest=++mineGeneration;
 for(const [id,tab] of [['listings-tab','listings'],['reservations-tab','reservations'],['received-tab','received']]){const selected=myTab===tab;$(id).className=selected?'primary':'ghost';$(id).setAttribute('aria-pressed',String(selected));}
 const copy={listings:['I miei annunci','In evidenza ciò che è ancora disponibile. Gli annunci terminati sono nello storico.'],reservations:['I miei ritiri','Qui trovi i tuoi ritiri da effettuare. I ritiri terminati sono nello storico.'],received:['Consegne dei miei annunci','Qui gestisci le persone che hanno prenotato il tuo cibo.']};$('my-summary-heading').textContent=copy[myTab][0];$('my-summary-description').textContent=copy[myTab][1];$('my-content').innerHTML='<p>Caricamento…</p>';
 const all=await rpc('saveat_my_reservations');if(mineRequest!==mineGeneration)return;
 if(myTab==='listings'){
 const {data,error}=await db.from('saveat_listings').select('*,saveat_items(*),saveat_municipalities(name,province)').eq('owner_id',session.user.id).order('created_at',{ascending:false}).limit(100);if(mineRequest!==mineGeneration)return;if(error)throw error;
 const pendingFor=l=>all.filter(r=>r.listing_id===l.id&&['reserved','confirmed'].includes(r.status));const state=l=>{if((l.status==='closed'||new Date(l.pickup_end)<=new Date())&&pendingFor(l).length)return 'pending';if(!l.saveat_items.some(i=>Number(i.available)>0)&&!pendingFor(l).length&&all.some(r=>r.listing_id===l.id&&r.status==='collected'))return 'completed';if(l.status==='closed')return 'cancelled';return new Date(l.pickup_end)<=new Date()?'expired':l.saveat_items.some(i=>Number(i.available)>0)?'available':'reserved';};
 const render=l=>{const s=state(l),pending=all.filter(r=>r.listing_id===l.id&&['reserved','confirmed'].includes(r.status)),labels={pending:'Annuncio terminato · consegna da confermare',completed:'Consegne completate',available:'Disponibile',reserved:'Tutto prenotato',cancelled:'Annuncio annullato',expired:'Periodo di ritiro terminato'};return '<article class="card padded summary-listing state-'+s+'"><span class="pill">Pubblicato da te · '+labels[s]+'</span><h2>'+esc(l.title)+'</h2>'+descriptionBlock(l.description)+paymentSummary(l.payment_methods,l.saveat_items.some(i=>Number(i.price)>0))+'<p>Consegna entro '+esc(when(l.pickup_end))+'</p><p>'+l.saveat_items.map(i=>esc(i.name)+': '+(s==='available'?esc(i.available)+' disponibili su ':'')+esc(i.quantity)+' '+esc(i.unit)).join('<br>')+'</p>'+(s==='cancelled'?'<p class="small">Non è più visibile nella ricerca e non si può prenotare.</p>':'')+(pending.length?'<p class="pending-pickup"><b>'+pending.length+' consegne da gestire</b> · '+pending.filter(r=>r.customer_collected_at).length+' segnalati dal cliente</p>':'')+'<div class="row"><button class="'+(pending.length?'primary':'ghost')+'" data-reservations="'+l.id+'">'+(pending.length?'Gestisci consegne':'Vedi prenotazioni')+'</button><a class="btn ghost" href="#scheda/'+l.id+'">Dettagli</a>'+'</div>'+ownListingActions(l)+'</article>';};
 $('my-content').innerHTML=summaryGroup('Consegne da completare',data.filter(l=>state(l)==='pending'),render)+summaryGroup('Disponibili',data.filter(l=>state(l)==='available'),render)+summaryGroup('Tutto prenotato',data.filter(l=>state(l)==='reserved'),render)+summaryGroup('Consegne completate',data.filter(l=>state(l)==='completed'),render,true)+summaryGroup('Annunci annullati',data.filter(l=>state(l)==='cancelled'),render,true)+summaryGroup('Periodo terminato',data.filter(l=>state(l)==='expired'),render,true)||(data.length?'':'<p class="empty">Non hai ancora pubblicato annunci.</p>');
 if(data.length&&!data.some(l=>['available','reserved','pending'].includes(state(l))))$('my-content').insertAdjacentHTML('afterbegin','<p class="empty">Non hai annunci disponibili. Puoi consultare lo storico qui sotto.</p>');
 document.querySelectorAll('[data-reservations]').forEach(b=>b.onclick=()=>{reservationFilter=b.dataset.reservations;myTab='received';run(b,loadMine);});
 bindCloseActions();bindDeleteActions();return;}
 const category=all.filter(r=>myTab==='received'?r.owner_id===session.user.id:r.owner_id!==session.user.id),data=reservationFilter?category.filter(r=>r.listing_id===reservationFilter):category;
 const active=data.filter(r=>['reserved','confirmed'].includes(r.status)),filterNote=reservationFilter?'<p class="ethic">Stai vedendo solo le consegne dell’annuncio selezionato. <button id="show-all-received" class="ghost">Mostra tutte le consegne</button></p>':'';
 $('my-content').innerHTML=filterNote+(active.length?summaryGroup(myTab==='received'?'Da consegnare':'Da ritirare',active,reservationSummaryCard):'<p class="empty">'+(myTab==='received'?'Nessuna consegna da effettuare.':'Non hai ritiri in programma.')+'</p>')+summaryGroup(myTab==='received'?'Consegne completate':'Ritiri completati',data.filter(r=>r.status==='collected'),reservationSummaryCard,true)+summaryGroup('Prenotazioni annullate',data.filter(r=>r.status==='cancelled'),reservationSummaryCard,true)+summaryGroup(myTab==='received'?'Prenotazioni scadute':'Ritiri scaduti',data.filter(r=>r.status==='expired'),reservationSummaryCard,true);
 bindCloseActions();bindDeleteActions();if($('show-all-received'))$('show-all-received').onclick=()=>{reservationFilter=null;run($('show-all-received'),loadMine);};
 document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>run(b,async()=>{await rpc('saveat_report_collection',{p_id:b.dataset.report});await loadMine();notice('Ritiro segnalato. Chi pubblica può ora confermarlo.');}));
 document.querySelectorAll('[data-transition]').forEach(b=>b.onclick=()=>{if(b.dataset.transition==='cancelled'&&!confirm('Annullare la prenotazione?'))return;run(b,async()=>{const state=await rpc('saveat_transition',{p_id:b.dataset.id,p_status:b.dataset.transition});await loadMine();notice(state==='collected'?'Consegna confermata.':'Stato aggiornato: '+statusNames[state]+'.');});});}
function cityPicker(prefix,onPick){const input=$(prefix+'-city'),box=$(prefix+'-city-options');let timer,sequence=0;input.addEventListener('input',()=>{onPick(null);clearTimeout(timer);const n=++sequence;const text=input.value.trim();box.hidden=true;input.setAttribute('aria-expanded','false');if(text.length<2||!db)return;timer=setTimeout(async()=>{try{const {data,error}=await db.from('saveat_municipalities').select('code,name,province,latitude,longitude').ilike('name',text.replace(/[%,_]/g,'')+'%').order('name').limit(12);if(error)throw error;if(n!==sequence)return;box.replaceChildren();data.forEach(c=>{const b=document.createElement('button');b.type='button';b.role='option';b.textContent=c.name+' ('+c.province+')';b.onclick=()=>{onPick(c);input.value=b.textContent;box.hidden=true;input.setAttribute('aria-expanded','false');input.focus();};box.append(b);});box.hidden=!data.length;input.setAttribute('aria-expanded',String(!!data.length));}catch(e){notice(errorText(e),true);}},180);});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&!box.hidden){e.preventDefault();box.querySelector('button')?.focus();}if(e.key==='Escape'){box.hidden=true;input.setAttribute('aria-expanded','false');}});box.addEventListener('keydown',e=>{const buttons=[...box.querySelectorAll('button')],index=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(e.key==='Escape'){box.hidden=true;input.setAttribute('aria-expanded','false');input.focus();}});document.addEventListener('click',e=>{if(!input.parentElement.contains(e.target)){box.hidden=true;input.setAttribute('aria-expanded','false');}});}
function safeConfig(url,key){const u=new URL(url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.username||u.password||u.pathname!=='/')throw new Error('Usa il Project URL https://…supabase.co del progetto.');if(key.startsWith('sb_secret_'))throw new Error('Questa è una chiave segreta. Usa la publishable key.');if(!key.startsWith('sb_publishable_')){try{const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.role!=='anon')throw Error();}catch{throw new Error('Usa una publishable key o la chiave anon pubblica.');}}return {url:u.origin,key};}
